function esc(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function linkify(text) {
  const spaced = text
    .replace(/([!?])([A-Za-z])/g, "$1 $2")
    .replace(/([^\s])(https?:\/\/)/g, "$1 $2");
  return esc(spaced).replace(/(https?:\/\/[^\s<&]+)/g, (url) => {
    const glued = url.match(/^(https?:\/\/.*\d)([A-Z][a-z].*)$/);
    const href = glued ? glued[1] : url;
    const rest = glued ? glued[2] : "";
    return '<a href="' + href + '" target="_blank" rel="noopener">' + href + "</a>" + rest;
  });
}
function dayLabel(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-US", {
    weekday: "long", month: "long", day: "numeric", timeZone: "UTC"
  });
}
function initials(post) {
  if (post.handle === "realDonaldTrump") return "DT";
  if (post.handle === "WhiteHouse") return "WH";
  return "RR";
}
function accountColor(post) {
  if (post.platform !== "X") return "var(--truth)";
  if (post.handle === "RapidResponse47") return "var(--x-rapid)";
  return "var(--x-whitehouse)";
}
function platformColor(post) {
  return post.platform === "X" ? "var(--plat-x)" : "var(--plat-truth)";
}
function num(n) {
  n = Number(n) || 0;
  if (n < 1000) return n.toLocaleString("en-US");
  const scaled = n >= 1000000 ? n / 1000000 : n / 1000;
  const rounded = Math.round(scaled * 10) / 10;
  const text = Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
  return text + (n >= 1000000 ? "m" : "k");
}
function asOf(post) {
  if (!post.collectedAt) return "";
  const dt = new Date(post.collectedAt);
  if (Number.isNaN(dt.getTime())) return "";
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Los_Angeles",
    hour: "numeric", minute: "numeric", hour12: true,
    month: "numeric", day: "numeric", year: "2-digit"
  }).formatToParts(dt);
  const get = (type) => parts.find((part) => part.type === type).value;
  const minute = get("minute");
  const ampm = get("dayPeriod").toLowerCase().replace(/\./g, "");
  const clock = minute === "00" ? get("hour") + ampm : get("hour") + ":" + minute + ampm;
  return "as of " + clock + " " + get("month") + "/" + get("day") + "/" + get("year");
}
function accountLabel(post) {
  return post.platform === "X" ? "X: " + post.account : "Truth Social";
}
function accountIcon(post) {
  const file = post.handle === "WhiteHouse" ? "icons/whitehouse.png"
    : post.handle === "RapidResponse47" ? "icons/rapid.png"
    : "icons/truth.png";
  return '<img class="acct-icon" src="' + file + '" alt="">';
}
function countsPhrase(post) {
  const pulled = asOf(post);
  return num(post.likes) + " likes · " + num(post.replies) + " replies · " + num(post.boosts) + " " + esc(post.boostLabel)
    + (pulled ? " · " + pulled : "");
}
function platformOk(post) {
  return !state.hidden.has(post.handle);
}
function queryOk(post) {
  const q = state.q.trim().toLowerCase();
  if (!q) return true;
  const hay = [post.summary, (post.topics || []).join(" "), post.text, post.account, post.handle, post.platform, post.repostOf, post.time, post.hour, post.day, dayLabel(post.day)].join("\n").toLowerCase();
  return q.split(/\s+/).every((word) => hay.includes(word));
}
function matching() {
  return POSTS.filter((post) => platformOk(post) && queryOk(post));
}
function condensedWho(post) {
  const color = accountColor(post);
  return '<span class="who"><span class="avatar" style="background:' + color + '">' + initials(post) + "</span><span>"
    + '<span class="name">' + esc(post.account) + "</span>"
    + '<span class="handle"><span class="plat" style="color:' + color + '">' + esc(post.platform) + "</span>"
    + (post.repostOf ? ' · <span class="plat" style="color:' + color + '">Repost</span>' : "")
    + " · @" + esc(post.handle) + " · " + esc(post.time) + " · " + esc(dayLabel(post.day)) + "</span>"
    + "</span></span>";
}
function whoBlock(post) {
  const color = accountColor(post);
  return '<div class="who">' + accountIcon(post) + "<div>"
    + '<div class="name">' + esc(accountLabel(post)) + "</div>"
    + '<div class="handle"><span class="plat" style="color:' + color + '">' + esc(post.platform) + "</span>"
    + (post.repostOf ? ' · <span class="plat" style="color:' + color + '">Repost</span>' : "")
    + " · @" + esc(post.handle) + " · " + esc(post.time) + " · " + esc(dayLabel(post.day)) + "</div>"
    + "</div></div>";
}
function countsLine(post) {
  return '<p class="counts">' + countsPhrase(post) + "</p>";
}
function openLink(post) {
  const label = post.platform === "X" ? "Open on X" : "Open on Truth Social";
  return '<a class="original" href="' + esc(post.url) + '" target="_blank" rel="noopener">' + label + "</a>";
}
function postBody(post) {
  const pics = post.images.map((src) => '<img src="' + esc(src) + '" alt="">').join("");
  const picBlock = pics ? '<div class="pics' + (post.images.length > 1 ? " multi" : "") + '">' + pics + "</div>" : "";
  const body = post.text.trim() ? '<p class="text">' + linkify(post.text) + "</p>" : "";
  const noText = post.text.trim() ? "" : '<p class="no-text">(no text)</p>';
  return body + picBlock + noText;
}
function topicText(post) {
  return (post.topics || []).join(" · ");
}
function shortPlat(post) {
  return post.platform === "X" ? "X" : "Truth";
}
function opened(post) {
  return '<div class="opened soc">'
    + postBody(post) + countsLine(post) + openLink(post) + "</div>";
}
function card(post) {
  if (mode === "condensed" && state.density === "line") return lineCard(post);
  if (mode === "condensed" && state.density === "pair") return pairCard(post);
  const color = accountColor(post);
  return '<article class="post" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + whoBlock(post)
    + postBody(post)
    + countsLine(post)
    + openLink(post)
    + "</article>";
}
function lineCard(post) {
  const thumb = post.images.length
    ? '<img class="tick-thumb" alt="" src="' + esc(post.images[0]) + '" onerror="this.remove()">'
    : "";
  return '<article class="rowline" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + "<details><summary>"
    + '<span class="tick-time">' + esc(post.time) + "</span>"
    + '<span class="who-name">' + esc(accountLabel(post)) + "</span>"
    + '<span class="tick-line">' + esc(post.summary || "No summary yet") + "</span>"
    + thumb
    + "</summary>" + opened(post) + "</details></article>";
}
function pairCard(post) {
  const topic = topicText(post);
  const meta = '<span class="who-name">' + esc(accountLabel(post)) + "</span>"
    + (post.repostOf ? " · Repost" : "")
    + ' <span class="pair-counts">· ' + countsPhrase(post) + "</span>"
    + (topic ? ' · <span class="kw">' + esc(topic) + "</span>" : "");
  return '<article class="rowpair" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + "<details><summary>"
    + '<span class="tick-time">' + esc(post.time) + "</span>"
    + '<span class="icon-cell">' + accountIcon(post) + "</span>"
    + '<span class="pair-body">'
    + '<span class="pair-title">' + esc(post.summary || "No summary yet") + "</span>"
    + '<span class="pair-meta">' + meta + "</span>"
    + "</span></summary>" + opened(post) + "</details></article>";
}
function groupRow(post) {
  const topic = topicText(post);
  return '<details class="run-row"><summary>'
    + '<span class="tick-time">' + esc(post.time) + "</span>"
    + (post.repostOf ? '<span class="tick-flag">Repost</span>' : "")
    + '<span class="tick-line">' + esc(post.summary || "No summary yet") + "</span>"
    + (topic ? '<span class="tick-topic">' + esc(topic) + "</span>" : "")
    + '<span class="tick-likes">' + num(post.likes) + " likes</span>"
    + "</summary>" + opened(post) + "</details>";
}
function renderSpine(posts) {
  let html = '<div class="spine"><div class="spine-cols"><div class="col-truth">Truth Social</div><div class="col-time">Timeline</div><div class="col-x">X</div></div><div class="spine-track">';
  let lastDay = "";
  posts.forEach((post) => {
    if (post.day !== lastDay) {
      html += '<div class="spine-gap"><span>' + esc(dayLabel(post.day)) + "</span></div>";
      lastDay = post.day;
    }
    const side = post.platform === "Truth Social" ? "left" : "right";
    const cardHtml = card(post);
    html += '<div class="spine-item ' + side + '" style="--bar:' + platformColor(post) + '">'
      + '<div class="slot">' + (side === "left" ? cardHtml : "") + "</div>"
      + '<div class="hub"><span class="lbl">' + esc(post.time) + "</span></div>"
      + '<div class="slot">' + (side === "right" ? cardHtml : "") + "</div>"
      + "</div>";
  });
  return html + "</div></div>";
}
function dateRule(day) {
  return '<div class="date-rule"><span>' + esc(dayLabel(day)) + "</span></div>";
}
function renderCondensed(posts) {
  let html = "";
  let lastDay = "";
  posts.forEach((post) => {
    if (post.day !== lastDay) {
      html += dateRule(post.day);
      lastDay = post.day;
    }
    html += card(post);
  });
  return html;
}
function renderMerged(posts) {
  let html = "";
  let lastKey = "";
  posts.forEach((post) => {
    const key = post.day + "|" + post.hour;
    if (key !== lastKey) {
      html += '<h2 class="hour">' + esc(dayLabel(post.day)) + " · " + esc(post.hour) + "</h2>";
      lastKey = key;
    }
    html += card(post);
  });
  return html;
}
function renderGrouped(posts) {
  let html = "";
  let lastDay = "";
  let buffer = [];
  function flush() {
    if (!buffer.length) return;
    if (buffer.length === 1) html += lineCard(buffer[0]);
    else {
      const post = buffer[0];
      html += '<div class="run" style="--bar:' + platformColor(post) + '">'
        + '<div class="run-head">' + accountIcon(post) + '<span class="who-name">' + esc(accountLabel(post)) + "</span> · " + buffer.length + " posts</div>";
      buffer.forEach((item) => { html += groupRow(item); });
      html += "</div>";
    }
    buffer = [];
  }
  posts.forEach((post) => {
    if (post.day !== lastDay) {
      flush();
      html += dateRule(post.day);
      lastDay = post.day;
    }
    if (buffer.length && buffer[0].handle !== post.handle) flush();
    buffer.push(post);
  });
  flush();
  return html;
}
function render() {
  const posts = matching();
  const base = POSTS.filter(platformOk).length;
  const tally = document.getElementById("tally");
  tally.textContent = state.q.trim()
    ? posts.length + " of " + base + (base === 1 ? " post" : " posts")
    : posts.length + (posts.length === 1 ? " post" : " posts");
  const feed = document.getElementById("feed");
  if (!posts.length) {
    const q = state.q.trim();
    feed.innerHTML = '<div class="empty"><p>' + (q ? "No post in this sample matches “" + esc(q) + "”." : (state.hidden.size === 3 ? "Every account is switched off." : "Nothing in this view.")) + "</p></div>";
    return;
  }
  feed.innerHTML = mode === "spine"
    ? renderSpine(posts)
    : (mode === "condensed"
        ? (state.density === "group" ? renderGrouped(posts) : renderCondensed(posts))
        : renderMerged(posts));
}
let mode = MODE;
function setMode(next) {
  mode = next;
  document.body.dataset.mode = next;
  document.body.classList.toggle("mode-spine", mode === "spine");
  document.body.classList.toggle("mode-merged", mode === "merged");
  document.body.classList.toggle("mode-condensed", mode === "condensed");
  const viewName = mode === "spine" ? "Timeline" : (mode === "condensed" ? "Condensed Feed" : "Feed");
  document.title = "Commander in Feed — " + viewName;
  document.querySelectorAll("button[data-mode]").forEach((btn) => {
    if (btn.dataset.mode === mode) btn.setAttribute("aria-current", "page");
    else btn.removeAttribute("aria-current");
  });
  render();
}
document.getElementById("q").addEventListener("input", (event) => {
  state.q = event.target.value;
  render();
});
document.querySelectorAll("button[data-mode]").forEach((btn) => {
  btn.addEventListener("click", () => setMode(btn.dataset.mode));
});
document.querySelectorAll("button[data-density]").forEach((btn) => {
  btn.addEventListener("click", () => {
    state.density = btn.dataset.density;
    document.querySelectorAll("button[data-density]").forEach((other) => {
      if (other === btn) other.setAttribute("aria-current", "page");
      else other.removeAttribute("aria-current");
    });
    if (mode !== "condensed") setMode("condensed");
    else render();
  });
});
document.querySelectorAll("input[data-account]").forEach((box) => {
  box.addEventListener("change", () => {
    if (box.checked) state.hidden.delete(box.dataset.account);
    else state.hidden.add(box.dataset.account);
    render();
  });
});
render();
